import { Fragment, useEffect, useState } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import {
  AccordionBody,
  AccordionHeader,
  AccordionItem,
  Button,
  Card,
  Col,
  Input,
  Label,
  Row,
  Accordion,
  Modal,
  ModalHeader,
  ModalFooter,
} from "reactstrap";
import useSubscribers from "../../../hooks/use_subscribers";
import { ChevronDown } from "react-feather";
import ReactPaginate from "react-paginate";
import { useSkin } from "@hooks/useSkin";
import ProgressLoading from "../../../components/progress_loading";
import DataTable from "react-data-table-component";
import CustomButton from "../../../components/button";
import { columns } from "./datatable/columns";
import { useDispatch, useSelector } from "react-redux";
import { setDeleteModal } from "../../../redux/subscriber_slice";
import { useNavigate } from "react-router-dom";

const AllSubscribers = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { skin } = useSkin();
  const {
    getSubscribers,
    deleteSubscriber,
    subscribersData,
    filters,
    setFilters,
    paginates,
    setPaginates,
    loadings,
    openSearchbar,
    setOpenSearchbar,
  } = useSubscribers();

  const deleteModal = useSelector((state) => state.subscriber.deleteModal);
  const selectedRow = useSelector((state) => state.subscriber.selectedRow);

  const handlePagination = (page) => {
    setPaginates({ ...paginates, current: page.selected + 1 });
    getSubscribers(page.selected + 1, false);
  };

  const CustomPagination = () => (
    <ReactPaginate
      previousLabel=""
      nextLabel=""
      forcePage={paginates.current - 1}
      onPageChange={(page) => handlePagination(page)}
      pageCount={paginates.total}
      breakLabel="..."
      pageRangeDisplayed={2}
      marginPagesDisplayed={2}
      activeClassName="active"
      pageClassName="page-item"
      breakClassName="page-item"
      nextLinkClassName="page-link"
      pageLinkClassName="page-link"
      breakLinkClassName="page-link"
      previousLinkClassName="page-link"
      nextClassName="page-item next-item"
      previousClassName="page-item prev-item"
      containerClassName="pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1"
    />
  );

  const toggleSearchbar = (id) => {
    setOpenSearchbar(openSearchbar === id ? undefined : id);
  };

  return (
    <Fragment>
      <Breadcrumbs
        title="Subscribers List"
        data={[{ title: "Subscribers" }, { title: "Subscribers List" }]}
      />
      {/* filterbar */}
      <Card>
        <Accordion open={openSearchbar} toggle={toggleSearchbar}>
          <AccordionItem>
            <AccordionHeader targetId="1">Search subscriber</AccordionHeader>
            <AccordionBody accordionId="1">
              <Row>
                {/* imsi */}
                <Col xs="12" sm="6" md="4" className={"mb-1"}>
                  <Label for="imsi">IMSI</Label>
                  <Input
                    value={filters.imsi}
                    onChange={(e) =>
                      setFilters({ ...filters, imsi: e.target.value })
                    }
                    name="imsi"
                    id="imsi"
                    type="number"
                  />
                </Col>
                {/* msisdn */}
                <Col xs="12" sm="6" md="4" className={"mb-1"}>
                  <Label for="msisdn">MSISDN</Label>
                  <Input
                    value={filters.msisdn}
                    onChange={(e) => {
                      let numberRegex = /^[0-9+]+$/;
                      if (e.target.value.length > 0) {
                        if (numberRegex.test(e.target.value)) {
                          setFilters({ ...filters, msisdn: e.target.value });
                        }
                      } else {
                        setFilters({ ...filters, msisdn: "" });
                      }
                    }}
                    name="msisdn"
                    id="msisdn"
                  />
                </Col>
                {/* ue_ipv4_address */}
                <Col xs="12" sm="6" md="4" className={"mb-1"}>
                  <Label for="ue_ipv4_address">UE IPv4 Address</Label>
                  <Input
                    value={filters.ue_ipv4_address}
                    onChange={(e) =>
                      setFilters({
                        ...filters,
                        ue_ipv4_address: e.target.value,
                      })
                    }
                    name="ue_ipv4_address"
                    id="ue_ipv4_address"
                  />
                </Col>
                {/* ue_ipv6_address */}
                <Col xs="12" sm="6" md="4" className={"mb-1"}>
                  <Label for="ue_ipv6_address">UE IPv6 Address</Label>
                  <Input
                    value={filters.ue_ipv6_address}
                    onChange={(e) =>
                      setFilters({
                        ...filters,
                        ue_ipv6_address: e.target.value,
                      })
                    }
                    name="ue_ipv6_address"
                    id="ue_ipv6_address"
                  />
                </Col>
                {/* smf_ipv4_address */}
                <Col xs="12" sm="6" md="4" className={"mb-1"}>
                  <Label for="smf_ipv4_address">SMF IPv4 Address</Label>
                  <Input
                    value={filters.smf_ipv4_address}
                    onChange={(e) =>
                      setFilters({
                        ...filters,
                        smf_ipv4_address: e.target.value,
                      })
                    }
                    name="smf_ipv4_address"
                    id="smf_ipv4_address"
                  />
                </Col>
                {/* smf_ipv6_address */}
                <Col xs="12" sm="6" md="4" className={"mb-1"}>
                  <Label for="smf_ipv6_address">SMF IPv6 Address</Label>
                  <Input
                    value={filters.smf_ipv6_address}
                    onChange={(e) =>
                      setFilters({
                        ...filters,
                        smf_ipv6_address: e.target.value,
                      })
                    }
                    name="smf_ipv6_address"
                    id="smf_ipv6_address"
                  />
                </Col>
                {/* actions */}
                <Col xs="12" className={"d-flex justify-content-end"}>
                  <Button
                    style={{ marginRight: 8 }}
                    color="danger"
                    onClick={() => {
                      setPaginates({ ...paginates, current: 1 });
                      getSubscribers(1, true);
                      setFilters({
                        imsi: "",
                        msisdn: "",
                        ue_ipv4_address: "",
                        ue_ipv6_address: "",
                        smf_ipv4_address: "",
                        smf_ipv6_address: "",
                      });
                    }}
                  >
                    Clear
                  </Button>
                  <Button
                    onClick={() => {
                      setPaginates({ ...paginates, current: 1 });
                      getSubscribers(1, false);
                    }}
                    style={{ width: 150 }}
                    color="primary"
                  >
                    Search
                  </Button>
                </Col>
              </Row>
            </AccordionBody>
          </AccordionItem>
        </Accordion>
      </Card>
      {/* datatable */}
      <div className="react-dataTable mv_datatable_container">
        <DataTable
          noDataComponent={loadings.getSubscribers ? "" : null}
          noHeader
          pagination
          columns={columns}
          paginationPerPage={paginates.per_page}
          className="react-dataTable"
          sortIcon={<ChevronDown size={10} />}
          paginationComponent={CustomPagination}
          data={subscribersData}
          theme={skin === "dark" ? "darkTheme" : ""}
        />
        {loadings.getSubscribers ? (
          <div className="datatable_loading_cover">
            <ProgressLoading />
          </div>
        ) : null}
      </div>
      {/* delete subscriber modal */}
      <Modal
        isOpen={deleteModal === 1}
        size={"md"}
        toggle={() => {
          dispatch(setDeleteModal(null));
        }}
        className="modal-dialog-centered"
        modalClassName="modal-primary"
        key={1}
      >
        <ModalHeader
          toggle={() => {
            dispatch(setDeleteModal(null));
          }}
        >
          Delete subscriber
        </ModalHeader>
        <ModalFooter className="w-100 d-flex justify-content-between">
          <Button
            disabled={loadings.deleteSubscriber}
            onClick={() => {
              dispatch(setDeleteModal(null));
            }}
            style={{ width: "calc(50% - 8px)" }}
            outline
            color={"secondary"}
          >
            Close
          </Button>
          <CustomButton
            loading={loadings.deleteSubscriber}
            type="button"
            style={{ width: "calc(50% - 8px)" }}
            color={"danger"}
            onClick={() => {
              deleteSubscriber(selectedRow.imsi);
            }}
          >
            Delete
          </CustomButton>
        </ModalFooter>
      </Modal>
    </Fragment>
  );
};
export default AllSubscribers;
